import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷四·7","description":"易小帖 - 卷四·7","frontmatter":{"title":"卷四·7","description":"易小帖 - 卷四·7"},"headers":[],"relativePath":"zh/classics/yixiaotie/101.md","filePath":"zh/classics/yixiaotie/101.md"}'),o={name:"zh/classics/yixiaotie/101.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷四·7",tabindex:"-1"},[r("卷四·7 "),e("a",{class:"header-anchor",href:"#卷四·7","aria-label":"Permalink to “卷四·7”"},"​")],-1),e("p",null,"鞶帶《釋文》作大帶，《左傳》「鞶厲游纓」註：「鞶紳帶也」。大抵命服先系革帶，使可懸鞞懸珮，然後加以拖紳之帶。謂之大帶，此與《內則》鞶袠，《春秋》鞶鑑註作婦飾者不同。特訟卦上九取象鞶帶，不可解。一謂上與三應，三為互離之二，如大帶之橫於腰，而闕其前。一謂三為離二，與上九乾三相應，離為牛，乾為衣，為圓比之牛為革帶，而加乾衣，鞶帶於其上。一謂離為股，乾為衣，加衣於股之上，則帶也。一謂鞶帶家廟之服，衣乾衣而入宗廟，是為鞶帶。說雖雜出，然舊人以象說易，多如此。至王弼以後，則並象俱抹煞耳。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
